 73→export function ShareDialog({
 74→  isOpen,
 75→  onClose,
 76→  item,
 77→  folderKey,
 78→  ipnsName,
 79→  parentFolderId,
 80→}: ShareDialogProps) {
 81→  const [activeTab, setActiveTab] = useState<'direct' | 'invite'>('direct');
 82→  const [pubKeyInput, setPubKeyInput] = useState('');
 83→  const [error, setError] = useState<string | null>(null);
 84→  const [success, setSuccess] = useState<string | null>(null);
 85→  const [isSharing, setIsSharing] = useState(false);
 86→  const [progress, setProgress] = useState<{ current: number; total: number } | null>(null);
 87→  const [recipients, setRecipients] = useState<SentShare[]>([]);
 88→  const [recipientsLoading, setRecipientsLoading] = useState(false);
 89→  const [recipientsFetched, setRecipientsFetched] = useState(false);
 90→  const [confirmRevokeId, setConfirmRevokeId] = useState<string | null>(null);
 91→  const [revokingId, setRevokingId] = useState<string | null>(null);
 92→
 93→  const inputRef = useRef<HTMLInputElement>(null);
 94→  const directTabRef = useRef<HTMLButtonElement>(null);
 95→  const inviteTabRef = useRef<HTMLButtonElement>(null);
 96→
 97→  // Fetch existing recipients when dialog opens
 98→  useEffect(() => {
 99→    if (!isOpen) {
100→      // Reset state on close
101→      setActiveTab('direct');
102→      setPubKeyInput('');
103→      setError(null);
104→      setSuccess(null);
105→      setIsSharing(false);
106→      setProgress(null);
107→      setConfirmRevokeId(null);
108→      setRevokingId(null);
109→      setRecipients([]);
110→      setRecipientsLoading(false);
111→      setRecipientsFetched(false);
112→      return;
113→    }
114→
115→    let cancelled = false;
116→    setRecipientsLoading(true);
117→
118→    (async () => {
119→      const pageSize = 100;
120→      let offset = 0;
121→      const allShares: SentShare[] = [];
122→
123→      // Paginate through all sent shares (API max 100 per page)
124→
125→      while (true) {
126→        const response = await sharesControllerGetSentShares({ limit: pageSize, offset });
127→        if (cancelled) return;
128→        const pageShares = response.shares
129→          .filter((s) => s.ipnsName === ipnsName)
130→          .map((s) => ({
131→            shareId: s.shareId,
132→            recipientPublicKey: s.recipientPublicKey,
133→            itemType: s.itemType as 'folder' | 'file',
134→            ipnsName: s.ipnsName,
135→            itemName: s.itemName,
136→            createdAt: String(s.createdAt),
137→          }));
138→        allShares.push(...pageShares);
139→        offset += response.shares.length;
140→        if (offset >= response.total || response.shares.length === 0) break;
141→      }
142→
143→      if (cancelled) return;
144→      setRecipients(allShares);
145→    })()
146→      .catch((err) => {
147→        if (cancelled) return;
148→        console.error('Failed to fetch sent shares:', err);
149→      })
150→      .finally(() => {
151→        if (!cancelled) {
152→          setRecipientsLoading(false);
153→          setRecipientsFetched(true);
154→        }
155→      });
156→
157→    return () => {
158→      cancelled = true;
159→    };
160→  }, [isOpen, ipnsName]);
161→
162→  const handleShare = useCallback(async () => {
163→    setError(null);
164→    setSuccess(null);
165→
166→    const key = pubKeyInput.trim();
167→
168→    // Validate format
169→    if (!isValidPublicKey(key)) {
170→      setError('invalid key format -- expected 0x04 + 128 hex chars');
171→      return;
172→    }
173→
174→    // Prevent sharing root folder
175→    if (parentFolderId === 'root' && item.type === 'folder') {
176→      // Check if item is the root folder itself (the one navigated to at root)
177→      const rootFolder = useFolderStore.getState().folders['root'];
178→      if (rootFolder && item.id === 'root') {
