    setError(null);
    setSuccess(null);
    setUpgradingId(share.shareId);

    try {
      // Get vault keypair for unwrapping IPNS key
      const vaultKeypair = useAuthStore.getState().vaultKeypair;
      if (!vaultKeypair) {
        setError('vault keypair not available');
