  1→/**
  2→ * useSharedNavigation -- Navigation hook for browsing shared content.
  3→ *
  4→ * Similar to useFolderNavigation but with a different key source:
  5→ * - Top level: shares received via share records
  6→ * - Folder browsing: re-wrapped keys from share_keys table
  7→ * - File download: re-wrapped fileKey from share_keys table
  8→ *
  9→ * Security: All keys are ECIES-wrapped for the current user.
 10→ * The server never sees plaintext keys.
 11→ */
 12→
 13→import { useState, useCallback, useEffect, useRef } from 'react';
 14→import {
 15→  decryptFolderMetadata,
 16→  decryptFileMetadata,
 17→  type FolderChild,
 18→  type FolderEntry,
 19→  type FilePointer,
 20→  type EncryptedFolderMetadata,
 21→  type EncryptedFileMetadata,
 22→} from '@cipherbox/core';
 23→import { unwrapKey, hexToBytes } from '@cipherbox/crypto';
 24→import { useAuthStore } from '../stores/auth.store';
 25→import { useShareStore, type ReceivedShare } from '../stores/share.store';
 26→import { fetchReceivedShares, fetchShareKeys, hideShare } from '../services/share.service';
 27→import { resolveIpnsRecord } from '../services/ipns.service';
 28→import { fetchFromIpfs } from '../lib/api/ipfs';
 29→import { downloadFile, triggerBrowserDownload } from '../services/download.service';
 30→import { useDownloadStore } from '../stores/download.store';
 31→
 32→/**
 33→ * Breadcrumb entry for shared navigation.
 34→ */
 35→export type SharedBreadcrumb = {
 36→  id: string;
 37→  name: string;
 38→};
 39→
 40→/**
 41→ * A shared item displayed in the top-level shared list.
 42→ * Extends the original FolderChild with sharing metadata.
 43→ */
 44→export type SharedListItem = {
 45→  share: ReceivedShare;
 46→  /** Resolved folder children (for folders), or null (for files / unresolved) */
 47→  children: FolderChild[] | null;
 48→  /** Folder key for this shared item (decrypted from share record) */
 49→  folderKey: Uint8Array | null;
 50→};
 51→
 52→type SharedView = 'list' | 'folder';
 53→
 54→type UseSharedNavigationReturn = {
 55→  currentView: SharedView;
 56→  currentShareId: string | null;
 57→  sharedItems: SharedListItem[];
 58→  folderChildren: FolderChild[];
 59→  folderKey: Uint8Array | null;
 60→  breadcrumbs: SharedBreadcrumb[];
 61→  isLoading: boolean;
 62→  error: string | null;
 63→  navigateToShare: (shareId: string) => Promise<void>;
 64→  navigateToSubfolder: (folderId: string, folderName: string) => Promise<void>;
 65→  navigateUp: () => void;
 66→  navigateToRoot: () => void;
 67→  navigateToBreadcrumb: (crumbIndex: number) => void;
 68→  downloadSharedFile: (item: FilePointer) => Promise<void>;
 69→  hideSharedItem: (shareId: string) => Promise<void>;
 70→};
 71→
 72→/**
 73→ * Hook for browsing shared content.
 74→ *
 75→ * Manages the "Shared with me" browsing experience.
 76→ * Top-level view shows received shares as a flat list.
 77→ * Clicking a shared folder navigates into it using re-wrapped keys.
 78→ */
 79→export function useSharedNavigation(): UseSharedNavigationReturn {
 80→  const [currentView, setCurrentView] = useState<SharedView>('list');
 81→  const [currentShareId, setCurrentShareId] = useState<string | null>(null);
 82→  const [sharedItems, setSharedItems] = useState<SharedListItem[]>([]);
 83→  const [folderChildren, setFolderChildren] = useState<FolderChild[]>([]);
 84→  const [folderKey, setFolderKey] = useState<Uint8Array | null>(null);
 85→  const [breadcrumbs, setBreadcrumbs] = useState<SharedBreadcrumb[]>([]);
 86→  const [isLoading, setIsLoading] = useState(true);
 87→  const [error, setError] = useState<string | null>(null);
 88→
 89→  // Navigation stack for folder browsing within a share
 90→  const navStackRef = useRef<
 91→    Array<{
 92→      folderId: string;
 93→      folderName: string;
 94→      children: FolderChild[];
 95→      folderKey: Uint8Array;
 96→    }>
 97→  >([]);
 98→
 99→  // Cache share keys per shareId with TTL to avoid refetching
100→  const shareKeysCache = useRef<
101→    Map<
102→      string,
103→      {
104→        keys: Array<{ keyType: 'file' | 'folder'; itemId: string; encryptedKey: string }>;
105→        fetchedAt: number;
106→      }
107→    >
108→  >(new Map());
109→
110→  /**
111→   * Load received shares on mount.
112→   */
113→  useEffect(() => {
114→    let cancelled = false;
115→
116→    async function loadShares() {
117→      setIsLoading(true);
118→      setError(null);
119→
120→      try {
121→        // Paginate through all received shares (API max 100 per page)
122→        const pageSize = 100;
123→        let offset = 0;
124→        const shares: ReceivedShare[] = [];
125→
126→        while (true) {
127→          const page = await fetchReceivedShares(pageSize, offset);
128→          if (cancelled) return;
129→          shares.push(...page.shares);
130→          offset += page.shares.length;
131→          if (offset >= page.total || page.shares.length === 0) break;
132→        }
133→
134→        useShareStore.getState().setReceivedShares(shares);
135→
136→        const items: SharedListItem[] = shares.map((share) => ({
137→          share,
138→          children: null,
139→          folderKey: null,
140→        }));
141→
142→        setSharedItems(items);
143→      } catch (err) {
144→        if (cancelled) return;
145→        console.error('Failed to load shared items:', err);
146→        setError('Failed to load shared items');
147→      } finally {
148→        if (!cancelled) {
149→          setIsLoading(false);
150→        }
151→      }
152→    }
153→
154→    loadShares();
155→    return () => {
156→      cancelled = true;
157→      // Zero all decrypted folder keys on unmount
158→      setFolderKey((prev) => {
159→        if (prev) prev.fill(0);
160→        return null;
161→      });
162→      for (const entry of navStackRef.current) {
163→        entry.folderKey.fill(0);
164→      }
165→      navStackRef.current = [];
166→    };
167→  }, []);
168→
169→  /** Cache TTL for share keys (60 seconds). */
170→  const SHARE_KEYS_CACHE_TTL = 60_000;
171→
172→  /**
173→   * Get share keys for a share, with TTL-based caching.
174→   */
175→  const getShareKeys = useCallback(async (shareId: string) => {
176→    const cached = shareKeysCache.current.get(shareId);
177→    if (cached && Date.now() - cached.fetchedAt < SHARE_KEYS_CACHE_TTL) {
178→      return cached.keys;
179→    }
180→
181→    const keys = await fetchShareKeys(shareId);
182→    shareKeysCache.current.set(shareId, { keys, fetchedAt: Date.now() });
183→    return keys;
184→  }, []);
185→
186→  /**
187→   * Navigate into a shared folder from the top-level list.
188→   */
189→  const navigateToShare = useCallback(
190→    async (shareId: string) => {
191→      const auth = useAuthStore.getState();
192→      if (!auth.vaultKeypair) {
193→        setError('No keypair available');
194→        return;
195→      }
196→
197→      const shareItem = sharedItems.find((s) => s.share.shareId === shareId);
198→      if (!shareItem) return;
199→
200→      const share = shareItem.share;
201→
202→      setIsLoading(true);
203→      setError(null);
204→
205→      try {
206→        // Unwrap the shared item's key with our private key
207→        const itemKey = await unwrapKey(
208→          hexToBytes(share.encryptedKey),
209→          auth.vaultKeypair.privateKey
210→        );
211→
212→        if (share.itemType === 'folder') {
213→          let folderKeyStored = false;
214→          try {
215→            // Resolve folder IPNS to get metadata
216→            const resolved = await resolveIpnsRecord(share.ipnsName);
217→            if (!resolved) {
218→              throw new Error('Could not resolve shared folder IPNS');
219→            }
220→
221→            // Fetch and decrypt folder metadata
222→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
223→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
224→            const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
225→            const metadata = await decryptFolderMetadata(encrypted, itemKey);
226→
227→            // Set folder state
228→            setCurrentView('folder');
229→            setCurrentShareId(shareId);
230→            setFolderChildren(metadata.children ?? []);
231→            setFolderKey(itemKey);
232→            folderKeyStored = true;
233→            setBreadcrumbs([{ id: shareId, name: share.itemName }]);
234→            navStackRef.current = [];
235→          } finally {
236→            if (!folderKeyStored) itemKey.fill(0);
237→          }
238→        } else {
239→          // For files, trigger download directly
240→          // itemKey is the parent folder key; downloadSharedFileFromShare unwraps its own copy
241→          itemKey.fill(0);
242→          await downloadSharedFileFromShare(share, auth.vaultKeypair.privateKey);
243→        }
244→      } catch (err) {
245→        console.error('Failed to navigate to shared item:', err);
246→        setError('Failed to open shared item');
247→      } finally {
248→        setIsLoading(false);
249→      }
250→    },
251→    [sharedItems]
252→  );
253→
254→  /**
255→   * Navigate into a subfolder within a shared folder.
256→   */
257→  const navigateToSubfolder = useCallback(
258→    async (folderId: string, folderName: string) => {
259→      const auth = useAuthStore.getState();
260→      if (!auth.vaultKeypair || !currentShareId) return;
261→
262→      setIsLoading(true);
263→      setError(null);
264→
265→      try {
266→        // Get re-wrapped keys for this share
267→        const keys = await getShareKeys(currentShareId);
268→
269→        // Find the re-wrapped folder key for this subfolder
270→        const keyRecord = keys.find((k) => k.keyType === 'folder' && k.itemId === folderId);
271→        if (!keyRecord) {
272→          throw new Error('No key available for this subfolder');
273→        }
274→
275→        // Unwrap the subfolder key
276→        const subfolderKey = await unwrapKey(
277→          hexToBytes(keyRecord.encryptedKey),
278→          auth.vaultKeypair.privateKey
279→        );
280→        let subfolderKeyStored = false;
281→
282→        try {
283→          // Find the subfolder entry to get its IPNS name
284→          const folderEntry = folderChildren.find(
285→            (c): c is FolderEntry => c.type === 'folder' && c.id === folderId
286→          );
287→          if (!folderEntry) {
288→            throw new Error('Subfolder not found in current children');
289→          }
290→
291→          // Resolve subfolder IPNS
292→          const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
293→          if (!resolved) {
294→            throw new Error('Could not resolve subfolder IPNS');
295→          }
296→
297→          // Fetch and decrypt subfolder metadata
298→          const encryptedBytes = await fetchFromIpfs(resolved.cid);
299→          const encryptedJson = new TextDecoder().decode(encryptedBytes);
300→          const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
301→          const metadata = await decryptFolderMetadata(encrypted, subfolderKey);
302→
303→          // Push current state to nav stack
304→          if (folderKey) {
305→            navStackRef.current.push({
306→              folderId: breadcrumbs[breadcrumbs.length - 1]?.id ?? '',
307→              folderName: breadcrumbs[breadcrumbs.length - 1]?.name ?? '',
308→              children: folderChildren,
309→              folderKey,
310→            });
311→          }
312→
313→          // Update state
314→          setFolderChildren(metadata.children ?? []);
315→          setFolderKey(subfolderKey);
316→          subfolderKeyStored = true;
317→          setBreadcrumbs((prev) => [...prev, { id: folderId, name: folderName }]);
318→        } finally {
319→          if (!subfolderKeyStored) subfolderKey.fill(0);
320→        }
321→      } catch (err) {
322→        console.error('Failed to navigate to subfolder:', err);
323→        setError('Failed to open subfolder');
324→      } finally {
325→        setIsLoading(false);
326→      }
327→    },
328→    [currentShareId, folderChildren, folderKey, breadcrumbs, getShareKeys]
329→  );
330→
331→  /**
332→   * Navigate back to the top-level shared list.
333→   * Zeroes all decrypted folder keys from memory before clearing state.
334→   */
335→  const navigateToRoot = useCallback(() => {
336→    // Zero current folder key
337→    if (folderKey) folderKey.fill(0);
338→    // Zero all nav stack folder keys
339→    for (const entry of navStackRef.current) {
340→      entry.folderKey.fill(0);
341→    }
342→    setCurrentView('list');
343→    setCurrentShareId(null);
344→    setFolderChildren([]);
345→    setFolderKey(null);
346→    setBreadcrumbs([]);
347→    navStackRef.current = [];
348→    setError(null);
349→  }, [folderKey]);
350→
351→  /**
352→   * Navigate up one level.
353→   */
354→  const navigateUp = useCallback(() => {
355→    if (navStackRef.current.length > 0) {
356→      // Zero current folder key before replacing
357→      if (folderKey) folderKey.fill(0);
358→      // Pop from nav stack
359→      const prev = navStackRef.current.pop()!;
360→      setFolderChildren(prev.children);
361→      setFolderKey(prev.folderKey);
362→      setBreadcrumbs((crumbs) => crumbs.slice(0, -1));
363→    } else if (currentView === 'folder') {
364→      // Back to top-level list
365→      navigateToRoot();
366→    }
367→  }, [currentView, folderKey, navigateToRoot]);
368→
369→  /**
370→   * Navigate directly to a breadcrumb level, zeroing all intermediate keys.
371→   * More efficient than calling navigateUp() in a loop.
372→   */
373→  const navigateToBreadcrumb = useCallback(
374→    (crumbIndex: number) => {
375→      const popsNeeded = breadcrumbs.length - 1 - crumbIndex;
376→      if (popsNeeded <= 0) return;
377→      // Zero the current folder key
378→      if (folderKey) folderKey.fill(0);
379→      // Zero and discard all intermediate keys
380→      for (let i = 0; i < popsNeeded - 1; i++) {
381→        const entry = navStackRef.current.pop();
382→        if (entry) entry.folderKey.fill(0);
383→      }
384→      // Restore the target level
385→      const target = navStackRef.current.pop();
386→      if (target) {
387→        setFolderChildren(target.children);
388→        setFolderKey(target.folderKey);
389→        setBreadcrumbs((crumbs) => crumbs.slice(0, crumbIndex + 1));
390→      }
391→    },
392→    [breadcrumbs, folderKey]
393→  );
394→
395→  /**
396→   * Download a shared file from the top-level list.
397→   * The share's encryptedKey wraps the parent folder key (needed to decrypt file metadata).
398→   * The actual file key is stored as a child key in share_keys.
399→   */
400→  async function downloadSharedFileFromShare(
401→    share: ReceivedShare,
402→    privateKey: Uint8Array
403→  ): Promise<void> {
404→    if (share.itemType !== 'file') return;
405→
406→    const downloadStore = useDownloadStore.getState();
407→
408→    try {
409→      downloadStore.startDownload(share.itemName);
410→
411→      // Unwrap the parent folder key from the share record
412→      const parentFolderKey = await unwrapKey(hexToBytes(share.encryptedKey), privateKey);
413→
414→      let fileMeta: Awaited<ReturnType<typeof decryptFileMetadata>>;
415→      try {
416→        // Resolve file IPNS metadata and decrypt with parent folder key
417→        const resolved = await resolveIpnsRecord(share.ipnsName);
418→        if (!resolved) {
419→          throw new Error('File metadata IPNS not found');
420→        }
421→
422→        const encryptedBytes = await fetchFromIpfs(resolved.cid);
423→        const encryptedJson = new TextDecoder().decode(encryptedBytes);
424→        const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
425→        fileMeta = await decryptFileMetadata(encrypted, parentFolderKey);
426→      } finally {
427→        parentFolderKey.fill(0);
428→      }
429→
430→      // Get the re-wrapped file key from share_keys
431→      const keys = await fetchShareKeys(share.shareId);
432→      const fileKeyRecord = keys.find((k) => k.keyType === 'file');
433→      if (!fileKeyRecord) {
434→        throw new Error('No re-wrapped file key available for this file');
435→      }
436→
437→      // Download and decrypt using the re-wrapped file key
438→      const plaintext = await downloadFile(
439→        {
440→          cid: fileMeta.cid,
441→          iv: fileMeta.fileIv,
442→          wrappedKey: fileKeyRecord.encryptedKey,
443→          originalName: share.itemName,
444→          encryptionMode: fileMeta.encryptionMode,
445→        },
446→        privateKey
447→      );
448→
449→      downloadStore.setDecrypting();
450→      triggerBrowserDownload(plaintext, share.itemName);
451→      downloadStore.setSuccess();
452→    } catch (err) {
453→      const message = (err as Error).message || 'Download failed';
454→      downloadStore.setError(message);
455→      console.error('Shared file download failed:', err);
456→    }
457→  }
458→
459→  /**
460→   * Download a shared file from within a shared folder.
461→   * Uses re-wrapped file keys from share_keys.
462→   */
463→  const downloadSharedFile = useCallback(
464→    async (item: FilePointer) => {
465→      const auth = useAuthStore.getState();
466→      if (!auth.vaultKeypair || !currentShareId || !folderKey) return;
467→
468→      const downloadStore = useDownloadStore.getState();
469→
470→      try {
471→        downloadStore.startDownload(item.name);
472→
473→        // Get share keys for file key lookup
474→        const keys = await getShareKeys(currentShareId);
475→
476→        // First resolve the file metadata using the parent folder key
477→        const resolved = await resolveIpnsRecord(item.fileMetaIpnsName);
478→        if (!resolved) {
479→          throw new Error('File metadata IPNS not found');
480→        }
481→
482→        const encryptedBytes = await fetchFromIpfs(resolved.cid);
483→        const encryptedJson = new TextDecoder().decode(encryptedBytes);
484→        const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
485→        const fileMeta = await decryptFileMetadata(encrypted, folderKey);
486→
487→        // Look for a re-wrapped file key in share_keys
488→        const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
489→
490→        if (!fileKeyRecord) {
491→          throw new Error('No re-wrapped file key available for this file');
492→        }
493→
494→        // Use re-wrapped file key from share_keys
495→        // downloadFile handles unwrapping internally via wrappedKey + privateKey
496→        const plaintext = await downloadFile(
497→          {
498→            cid: fileMeta.cid,
499→            iv: fileMeta.fileIv,
500→            wrappedKey: fileKeyRecord.encryptedKey,
501→            originalName: item.name,
502→            encryptionMode: fileMeta.encryptionMode,
503→          },
504→          auth.vaultKeypair.privateKey
505→        );
506→
507→        downloadStore.setDecrypting();
508→        triggerBrowserDownload(plaintext, item.name);
509→        downloadStore.setSuccess();
510→      } catch (err) {
511→        const message = (err as Error).message || 'Download failed';
512→        downloadStore.setError(message);
513→        console.error('Shared file download failed:', err);
514→      }
515→    },
516→    [currentShareId, folderKey, getShareKeys]
517→  );
518→
519→  /**
520→   * Hide a shared item from the user's view.
521→   */
