523→    try {
524→      await hideShare(shareId);
525→      useShareStore.getState().removeReceivedShare(shareId);
526→      setSharedItems((prev) => prev.filter((s) => s.share.shareId !== shareId));
527→    } catch (err) {
528→      console.error('Failed to hide share:', err);
529→      setError('Failed to hide shared item');
530→    }
531→  }, []);
532→
533→  return {
534→    currentView,
535→    currentShareId,
536→    sharedItems,
537→    folderChildren,
538→    folderKey,
539→    breadcrumbs,
540→    isLoading,
541→    error,
542→    navigateToShare,
543→    navigateToSubfolder,
544→    navigateUp,
545→    navigateToRoot,
546→    navigateToBreadcrumb,
547→    downloadSharedFile,
548→    hideSharedItem,
549→  };
550→}
