 42→/**
 43→ * React hook for folder CRUD operations (create, rename, move, delete).
 44→ *
 45→ * Operations delegate to CipherBoxClient SDK methods. The SDK handles
 46→ * crypto, metadata construction, and IPNS publishing internally. SDK
 47→ * events update the folder store via event subscriptions.
 48→ *
 49→ * The hook manages UI concerns: loading state, error handling, toasts,
 50→ * and store-level coordination (folder node management, share re-wrapping).
 51→ */
 52→export function useFolderMutations() {
 53→  const [state, setState] = useState<FolderOperationState>({
 54→    isLoading: false,
 55→    error: null,
 56→  });
 57→
 58→  /**
 59→   * Create a new folder via SDK.
 60→   *
 61→   * @param name - Folder name
 62→   * @param parentId - Parent folder ID (null for root, or folder UUID)
 63→   * @returns Created folder IPNS name and key
 64→   */
 65→  const handleCreate = useCallback(
 66→    async (name: string, parentId: string | null): Promise<{ ipnsName: string }> => {
 67→      setState({ isLoading: true, error: null });
 68→      try {
 69→        const folders = useFolderStore.getState().folders;
 70→
 71→        // Validate depth limit before creating (FOLD-03)
 72→        const parentDepth = folderService.getDepth(parentId, folders);
 73→        if (parentDepth >= MAX_FOLDER_DEPTH) {
 74→          throw new Error(`Cannot create folder: maximum depth of ${MAX_FOLDER_DEPTH} exceeded`);
 75→        }
 76→
 77→        // Resolve parent folder
 78→        const actualParentId = parentId ?? 'root';
 79→        const parentFolder = getParentFolder(actualParentId);
 80→        if (!parentFolder) {
 81→          throw new Error('Parent folder not found or vault not initialized');
 82→        }
 83→
 84→        // Ensure parent is registered in SDK's FolderTree
 85→        ensureFolderRegistered(parentFolder);
 86→
 87→        // Create folder via SDK (handles key gen, metadata update, IPNS publish)
 88→        const client = getSdkClient();
 89→        const result = await client.createFolder(parentFolder.ipnsName, name);
 90→
 91→        // SDK emits folder:updated -> store subscription updates parent's children
 92→        // But we also need to add the new folder as a store node so navigation works
 93→        const newFolderNode: FolderNode = {
 94→          id: result.id, // UUID from the FolderEntry in parent's children
 95→          name,
 96→          ipnsName: result.ipnsName,
 97→          parentId: actualParentId,
 98→          children: [],
 99→          isLoaded: true,
100→          isLoading: false,
101→          sequenceNumber: 1n,
102→          folderKey: result.folderKey,
103→          ipnsPrivateKey: result.ipnsPrivateKey,
104→        };
105→        useFolderStore.getState().setFolder(newFolderNode);
106→
107→        // Post-create re-wrapping is handled by the SDK's shareCallbacks.
108→        // The CipherBoxClient.createFolder() calls reWrapNewItems() internally.
109→
110→        setState({ isLoading: false, error: null });
111→        return { ipnsName: result.ipnsName };
112→      } catch (err) {
113→        const error = err instanceof Error ? err.message : 'Failed to create folder';
114→        setState({ isLoading: false, error });
115→        throw err;
116→      }
117→    },
118→    []
119→  );
120→
121→  /**
122→   * Rename a file or folder via SDK.
123→   *
124→   * @param itemId - ID of item to rename
125→   * @param itemType - 'file' or 'folder'
126→   * @param newName - New name
127→   * @param parentId - Parent folder ID
128→   */
129→  const handleRename = useCallback(
130→    async (
131→      itemId: string,
132→      itemType: 'file' | 'folder',
133→      newName: string,
134→      parentId: string
135→    ): Promise<void> => {
136→      setState({ isLoading: true, error: null });
137→      try {
138→        const parentFolder = getParentFolder(parentId);
139→        if (!parentFolder) throw new Error('Parent folder not found');
140→
141→        // Ensure parent is registered in SDK
142→        ensureFolderRegistered(parentFolder);
143→
144→        // Rename via SDK (handles metadata update, IPNS publish)
145→        const client = getSdkClient();
146→        await client.renameItem(parentFolder.ipnsName, itemId, newName);
147→
148→        // SDK emits folder:updated -> store subscription updates children
149→        // Also update the folder name in the store if renaming a folder
150→        if (itemType === 'folder') {
151→          useFolderStore.getState().updateFolderName(itemId, newName);
152→        }
153→
154→        setState({ isLoading: false, error: null });
155→      } catch (err) {
156→        const error = err instanceof Error ? err.message : 'Failed to rename';
157→        setState({ isLoading: false, error });
158→        throw err;
159→      }
160→    },
161→    []
162→  );
163→
164→  /**
165→   * Move a file or folder via SDK.
166→   *
167→   * @param itemId - ID of item to move
168→   * @param itemType - 'file' or 'folder'
169→   * @param sourceParentId - Current parent folder ID
170→   * @param destParentId - Destination parent folder ID
171→   */
172→  const handleMove = useCallback(
173→    async (
174→      itemId: string,
175→      itemType: 'file' | 'folder',
176→      sourceParentId: string,
177→      destParentId: string
178→    ): Promise<void> => {
179→      setState({ isLoading: true, error: null });
180→      try {
181→        const sourceFolder = getParentFolder(sourceParentId);
182→        const destFolder = getParentFolder(destParentId);
183→        if (!sourceFolder || !destFolder) {
184→          throw new Error('Source or destination folder not found');
185→        }
186→
187→        // Ensure both folders are registered in SDK
188→        ensureFolderRegistered(sourceFolder);
189→        ensureFolderRegistered(destFolder);
190→
191→        // Move via SDK (handles add-before-remove, both IPNS publishes)
192→        const client = getSdkClient();
193→        await client.moveItem(sourceFolder.ipnsName, destFolder.ipnsName, itemId);
194→
195→        // SDK emits folder:updated for both folders -> store subscription updates children
196→        // Also update parentId for moved folders
197→        if (itemType === 'folder') {
198→          const movedFolder = useFolderStore.getState().folders[itemId];
199→          if (movedFolder) {
200→            useFolderStore.getState().setFolder({
201→              ...movedFolder,
202→              parentId: destParentId,
203→            });
204→          }
205→        }
206→
207→        setState({ isLoading: false, error: null });
208→      } catch (err) {
209→        const error = err instanceof Error ? err.message : 'Failed to move';
210→        setState({ isLoading: false, error });
211→        throw err;
212→      }
213→    },
214→    []
215→  );
216→
217→  /**
218→   * Move multiple files/folders to a destination.
219→   *
220→   * Uses SDK moveItem for each item sequentially to preserve event ordering.
221→   *
222→   * @param items - Array of { id, type } to move
223→   * @param sourceParentId - Current parent folder ID
224→   * @param destParentId - Destination parent folder ID
225→   */
226→  const handleMoveItems = useCallback(
227→    async (
228→      items: Array<{ id: string; type: 'file' | 'folder' }>,
229→      sourceParentId: string,
230→      destParentId: string
231→    ): Promise<void> => {
232→      setState({ isLoading: true, error: null });
233→      try {
234→        const sourceFolder = getParentFolder(sourceParentId);
235→        const destFolder = getParentFolder(destParentId);
236→        if (!sourceFolder || !destFolder) {
237→          throw new Error('Source or destination folder not found');
238→        }
239→
240→        // Validate batch move preconditions
241→        const folders = useFolderStore.getState().folders;
242→        const itemIds = new Set(items.map((i) => i.id));
243→
244→        for (const item of items) {
245→          if (item.type === 'folder') {
246→            // Prevent moving folder into itself or descendant
247→            if (folderService.isDescendantOf(destFolder.id, item.id, folders)) {
248→              throw new Error(`Cannot move folder into itself or its subfolder`);
249→            }
250→
251→            // Depth limit check
252→            const destDepth = folderService.getDepth(destFolder.id, folders);
253→            const subtreeDepth = folderService.calculateSubtreeDepth(item.id, folders);
254→            if (destDepth + 1 + subtreeDepth > MAX_FOLDER_DEPTH) {
255→              throw new Error(
256→                `Cannot move: would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`
257→              );
258→            }
259→          }
260→        }
261→
262→        // Name collision check against destination
263→        const movedChildren = sourceFolder.children.filter((c) => itemIds.has(c.id));
264→        for (const child of movedChildren) {
265→          const nameExists = destFolder.children.some((c) => c.name === child.name);
266→          if (nameExists) {
267→            throw new Error(`An item named "${child.name}" already exists in the destination`);
268→          }
269→        }
270→
271→        // Ensure both folders are registered in SDK
272→        ensureFolderRegistered(sourceFolder);
273→        ensureFolderRegistered(destFolder);
274→
275→        // Move each item via SDK
276→        const client = getSdkClient();
277→        for (const item of items) {
278→          await client.moveItem(sourceFolder.ipnsName, destFolder.ipnsName, item.id);
279→
280→          if (item.type === 'folder') {
281→            const movedFolder = useFolderStore.getState().folders[item.id];
282→            if (movedFolder) {
283→              useFolderStore.getState().setFolder({ ...movedFolder, parentId: destParentId });
284→            }
285→          }
286→        }
287→
288→        setState({ isLoading: false, error: null });
289→      } catch (err) {
290→        const error = err instanceof Error ? err.message : 'Failed to move items';
291→        setState({ isLoading: false, error });
292→        throw err;
293→      }
294→    },
295→    []
296→  );
297→
298→  /**
299→   * Delete a file or folder via SDK.
300→   *
301→   * Uses deleteToBin for soft-delete (moves to recycle bin) when the SDK's
302→   * bin state is loaded, otherwise falls back to deleteItem (hard metadata delete)
303→   * with a fire-and-forget bin service call.
304→   *
305→   * @param itemId - ID of item to delete
306→   * @param itemType - 'file' or 'folder'
307→   * @param parentId - Parent folder ID
308→   */
309→  const handleDelete = useCallback(
310→    async (itemId: string, itemType: 'file' | 'folder', parentId: string): Promise<void> => {
311→      setState({ isLoading: true, error: null });
312→      try {
313→        const parentFolder = getParentFolder(parentId);
314→        if (!parentFolder) throw new Error('Parent folder not found');
315→
316→        // Ensure parent is registered in SDK
317→        ensureFolderRegistered(parentFolder);
318→
319→        const client = getSdkClient();
320→        const parentPath = buildFolderPath(parentId);
321→
322→        // Try soft-delete (move to bin) first; fall back to hard delete if bin not loaded
323→        try {
324→          await client.deleteToBin(parentFolder.ipnsName, itemId, parentPath);
325→        } catch (binErr) {
326→          // Bin not loaded -- fall back to hard metadata delete
327→          if (binErr instanceof BinNotLoadedError) {
328→            await client.deleteItem(parentFolder.ipnsName, itemId);
329→          } else {
330→            throw binErr;
331→          }
332→        }
333→
334→        // SDK emits folder:updated -> store subscription updates children
335→        // Remove folder subtree from store if deleting a folder
336→        if (itemType === 'folder') {
337→          const store = useFolderStore.getState();
338→          const removeRecursive = (folderId: string) => {
339→            const node = store.folders[folderId];
340→            if (node) {
341→              for (const child of node.children) {
342→                if (child.type === 'folder') removeRecursive(child.id);
343→              }
344→            }
345→            store.removeFolder(folderId);
346→          };
347→          removeRecursive(itemId);
348→        }
349→
350→        setState({ isLoading: false, error: null });
351→      } catch (err) {
352→        const error = err instanceof Error ? err.message : 'Failed to delete';
353→        setState({ isLoading: false, error });
354→        throw err;
355→      }
356→    },
357→    []
358→  );
359→
360→  /**
361→   * Delete multiple files/folders.
362→   *
363→   * @param items - Array of { id, type } to delete
364→   * @param parentId - Parent folder ID
365→   */
366→  const handleDeleteItems = useCallback(
367→    async (
368→      items: Array<{ id: string; type: 'file' | 'folder' }>,
369→      parentId: string
370→    ): Promise<void> => {
371→      setState({ isLoading: true, error: null });
372→      try {
373→        const parentFolder = getParentFolder(parentId);
374→        if (!parentFolder) throw new Error('Parent folder not found');
375→
376→        // Ensure parent is registered in SDK
377→        ensureFolderRegistered(parentFolder);
378→
379→        // Collect nested folder IDs to remove from store
380→        const folderIdsToRemove: string[] = [];
381→        const collectFolderIds = (folderId: string) => {
382→          folderIdsToRemove.push(folderId);
383→          const folders = useFolderStore.getState().folders;
384→          const folder = folders[folderId];
385→          if (!folder) return;
386→          for (const child of folder.children) {
387→            if (child.type === 'folder') {
388→              collectFolderIds(child.id);
389→            }
390→          }
391→        };
392→
393→        for (const item of items) {
394→          if (item.type === 'folder') {
395→            collectFolderIds(item.id);
396→          }
397→        }
398→
399→        // Delete each item via SDK (sequentially to maintain consistency)
400→        const client = getSdkClient();
401→        const parentPath = buildFolderPath(parentId);
402→
403→        for (const item of items) {
404→          // Re-register parent between deletes since SDK updates its internal state
405→          const freshParent = getParentFolder(parentId);
406→          if (freshParent) ensureFolderRegistered(freshParent);
407→
408→          // Try soft-delete (bin) first; fall back to hard delete
409→          try {
410→            await client.deleteToBin(parentFolder.ipnsName, item.id, parentPath);
411→          } catch (binErr) {
412→            if (binErr instanceof BinNotLoadedError) {
413→              await client.deleteItem(parentFolder.ipnsName, item.id);
414→            } else {
415→              throw binErr;
416→            }
417→          }
418→        }
419→
420→        // Remove nested folders from store
421→        const store = useFolderStore.getState();
422→        for (const folderId of folderIdsToRemove) {
423→          store.removeFolder(folderId);
424→        }
425→
426→        setState({ isLoading: false, error: null });
427→      } catch (err) {
428→        const error = err instanceof Error ? err.message : 'Failed to delete items';
429→        setState({ isLoading: false, error });
430→        throw err;
431→      }
432→    },
433→    []
434→  );
435→
436→  return {
437→    ...state,
438→    createFolder: handleCreate,
439→    renameItem: handleRename,
440→    moveItem: handleMove,
441→    moveItems: handleMoveItems,
442→    deleteItem: handleDelete,
443→    deleteItems: handleDeleteItems,
444→  };
445→}
