 39→  sentShares: SentShare[];
 40→  isLoadingReceived: boolean;
 41→  isLoadingSent: boolean;
 42→  lastReceivedFetchedAt: number | null;
 43→  lastSentFetchedAt: number | null;
 44→
 45→  // Actions
 46→  setReceivedShares: (shares: ReceivedShare[]) => void;
