 57→/**
 58→ * Share store for managing sent/received share state.
 59→ *
 60→ * Maintains the in-memory lists of shares the user has
 61→ * sent to others and received from others.
 62→ *
 63→ * Call clearShares() on logout to reset state.
 64→ */
 65→export const useShareStore = create<ShareState>((set) => ({
 66→  // State
 67→  receivedShares: [],
 68→  sentShares: [],
 69→  isLoadingReceived: false,
 70→  isLoadingSent: false,
 71→  lastReceivedFetchedAt: null,
 72→  lastSentFetchedAt: null,
 73→
 74→  // Actions
 75→  setReceivedShares: (shares) =>
 76→    set({ receivedShares: shares, isLoadingReceived: false, lastReceivedFetchedAt: Date.now() }),
