416→                }}
417→              />
418→            ))}
419→          </div>
420→        </div>
421→      )}
422→
423→      {/* Empty folder */}
424→      {!isLoading && !hasChildren && !error && (
425→        <div className="empty-state" data-testid="shared-empty-folder">
426→          <div className="empty-state-content">
427→            <pre className="empty-state-ascii" aria-hidden="true">
428→              {sharedEmptyArt}
429→            </pre>
430→            <p className="empty-state-text">{'// EMPTY SHARED FOLDER'}</p>
431→            <p className="empty-state-hint">this shared folder has no contents</p>
432→          </div>
433→        </div>
434→      )}
435→
436→      {/* Read-only context menu */}
437→      {contextMenu.visible && contextMenu.item && (
438→        <ContextMenu
439→          x={contextMenu.x}
440→          y={contextMenu.y}
441→          item={contextMenu.item}
442→          selectedCount={1}
443→          onClose={contextMenu.hide}
444→          onDownload={contextMenu.item.type === 'file' ? handleDownload : undefined}
445→          onEdit={
446→            contextMenu.item.type === 'file' && isTextFile(contextMenu.item.name)
447→              ? handleEditClick
448→              : undefined
449→          }
450→          onPreview={
451→            contextMenu.item.type === 'file' && isPreviewableFile(contextMenu.item.name)
452→              ? handlePreviewClick
453→              : undefined
454→          }
455→          onRename={() => {}}
456→          onDelete={() => {}}
457→          onDetails={handleDetailsClick}
458→          readOnly
459→        />
460→      )}
461→
462→      {/* Details dialog */}
463→      <DetailsDialog
464→        open={detailsDialog.open}
465→        onClose={() => setDetailsDialog({ open: false, item: null })}
466→        item={detailsDialog.item}
467→        folderKey={folderKey}
468→        parentFolderId=""
469→      />
470→
471→      {/* Text viewer dialog (read-only) */}
472→      <TextEditorDialog
473→        open={editorDialog.open}
474→        onClose={() => setEditorDialog({ open: false, item: null })}
475→        item={editorDialog.item && isFilePointer(editorDialog.item) ? editorDialog.item : null}
476→        parentFolderId=""
477→        folderKey={folderKey}
478→        readOnly
479→        shareId={currentShareId}
480→      />
481→
482→      {/* Image preview dialog */}
483→      <ImagePreviewDialog
484→        open={imagePreviewDialog.open}
485→        onClose={() => setImagePreviewDialog({ open: false, item: null })}
486→        item={
487→          imagePreviewDialog.item && isFilePointer(imagePreviewDialog.item)
488→            ? imagePreviewDialog.item
489→            : null
490→        }
491→        folderKey={folderKey}
492→        shareId={currentShareId}
493→      />
494→
495→      {/* PDF preview dialog */}
496→      <PdfPreviewDialog
497→        open={pdfPreviewDialog.open}
498→        onClose={() => setPdfPreviewDialog({ open: false, item: null })}
499→        item={
500→          pdfPreviewDialog.item && isFilePointer(pdfPreviewDialog.item)
501→            ? pdfPreviewDialog.item
502→            : null
503→        }
504→        folderKey={folderKey}
505→        shareId={currentShareId}
506→      />
507→
508→      {/* Audio player dialog */}
509→      <AudioPlayerDialog
510→        open={audioPlayerDialog.open}
511→        onClose={() => setAudioPlayerDialog({ open: false, item: null })}
512→        item={
513→          audioPlayerDialog.item && isFilePointer(audioPlayerDialog.item)
514→            ? audioPlayerDialog.item
515→            : null
516→        }
517→        folderKey={folderKey}
518→        shareId={currentShareId}
519→      />
520→
521→      {/* Video player dialog */}
522→      <VideoPlayerDialog
523→        open={videoPlayerDialog.open}
524→        onClose={() => setVideoPlayerDialog({ open: false, item: null })}
525→        item={
526→          videoPlayerDialog.item && isFilePointer(videoPlayerDialog.item)
527→            ? videoPlayerDialog.item
528→            : null
529→        }
530→        folderKey={folderKey}
531→        shareId={currentShareId}
532→      />
533→    </div>
534→  );
535→}
536→
537→/**
538→ * Row component for the top-level shared items list.
539→ */
540→function SharedListRow({
541→  sharedItem,
542→  onOpen,
543→  onContextMenu,
544→}: {
545→  sharedItem: SharedListItem;
546→  onOpen: () => void;
547→  onContextMenu: (e: MouseEvent) => void;
548→}) {
549→  const { share } = sharedItem;
550→  const isFolder = share.itemType === 'folder';
551→  const icon = isFolder ? '\uD83D\uDCC1' : '\uD83D\uDCC4';
552→  const date = new Date(share.createdAt).toLocaleDateString();
553→
554→  return (
555→    <div
556→      className="file-list-row shared-list-row"
557→      role="row"
558→      tabIndex={0}
559→      onDoubleClick={onOpen}
560→      onContextMenu={(e) => {
561→        e.preventDefault();
562→        onContextMenu(e);
563→      }}
564→      onKeyDown={(e) => {
565→        if (e.key === 'Enter' || e.key === ' ') {
566→          e.preventDefault();
567→          onOpen();
568→        }
569→      }}
570→    >
571→      <div className="file-list-cell file-list-cell-name" role="gridcell">
572→        <span className="file-icon">{icon}</span>
573→        <span className="file-name">
574→          {share.itemName}
575→          {isFolder ? '/' : ''}
576→        </span>
577→        <span className="shared-ro-badge">[RO]</span>
578→      </div>
579→      <div className="file-list-cell shared-by-cell" role="gridcell">
580→        {truncatePubkey(share.sharerPublicKey)}
581→      </div>
582→      <div className="file-list-cell file-list-cell-date" role="gridcell">
583→        {date}
584→      </div>
585→    </div>
586→  );
587→}
588→
589→/**
590→ * Row component for items within a shared folder.
591→ */
592→function SharedFolderRow({
593→  item,
594→  onContextMenu,
595→  onDoubleClick,
596→}: {
597→  item: FolderChild;
598→  onContextMenu: (e: MouseEvent) => void;
599→  onDoubleClick: () => void;
600→}) {
601→  const isFolder = item.type === 'folder';
602→  const icon = isFolder ? '\uD83D\uDCC1' : '\uD83D\uDCC4';
603→  const date = item.modifiedAt ? new Date(item.modifiedAt).toLocaleDateString() : '--';
604→
605→  return (
606→    <div
607→      className="file-list-row"
608→      role="row"
609→      tabIndex={0}
610→      onDoubleClick={onDoubleClick}
611→      onContextMenu={(e) => {
612→        e.preventDefault();
613→        onContextMenu(e);
614→      }}
615→      onKeyDown={(e) => {
616→        if (e.key === 'Enter' || e.key === ' ') {
617→          e.preventDefault();
618→          onDoubleClick();
619→        }
620→      }}
621→    >
622→      <div className="file-list-cell file-list-cell-name" role="gridcell">
623→        <span className="file-icon">{icon}</span>
624→        <span className="file-name">
625→          {item.name}
626→          {isFolder ? '/' : ''}
627→        </span>
628→        <span className="shared-ro-badge">[RO]</span>
629→      </div>
630→      <div className="file-list-cell file-list-cell-size" role="gridcell">
631→        --
632→      </div>
